selector_to_html = {"a[href=\"#module-summary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Summary<a class=\"headerlink\" href=\"#module-summary\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"mcp_client/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_client<a class=\"headerlink\" href=\"#module-mcp.client.mcp_client\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Main Implementation.</p><p>This module provides the main MCPClient class that orchestrates the MCP\nprotocol communication. It combines the transport layer, protocol layer,\nand provides a high-level interface for MCP operations.</p>", "a[href=\"#basic-connection\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Connection<a class=\"headerlink\" href=\"#basic-connection\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#context-manager-usage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Context Manager Usage<a class=\"headerlink\" href=\"#context-manager-usage\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#key-components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Components<a class=\"headerlink\" href=\"#key-components\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"exceptions/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">exceptions<a class=\"headerlink\" href=\"#module-mcp.client.exceptions\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Exception Classes.</p><p>This module defines all exception types used by the MCP client implementation.\nThese exceptions follow the MCP protocol error specifications and provide\ndetailed error information for debugging and error handling.</p>", "a[href=\"#transport-classes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Transport Classes<a class=\"headerlink\" href=\"#transport-classes\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#exception-classes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exception Classes<a class=\"headerlink\" href=\"#exception-classes\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#module-mcp.client\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">client<a class=\"headerlink\" href=\"#module-mcp.client\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Implementation Package.</p><p>This package provides native MCP protocol client implementation for connecting\nto and communicating with MCP servers according to the Model Context Protocol\nspecification.</p>", "a[href=\"#available-classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Available Classes<a class=\"headerlink\" href=\"#available-classes\" title=\"Link to this heading\">\u00b6</a></h2><h3>Transport Classes<a class=\"headerlink\" href=\"#transport-classes\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"protocol/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">protocol<a class=\"headerlink\" href=\"#module-mcp.client.protocol\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Protocol Implementation.</p><p>This module implements the Model Context Protocol (MCP) JSON-RPC based\ncommunication protocol. It handles the protocol-level details including\nmessage framing, request/response matching, and capability negotiation.</p>", "a[href=\"connection/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">connection<a class=\"headerlink\" href=\"#module-mcp.client.connection\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Connection Management.</p><p>This module provides connection management utilities for MCP clients.\nIt handles connection pooling, health monitoring, and connection lifecycle\nmanagement for different transport types.</p>", "a[href=\"#usage-examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Usage Examples<a class=\"headerlink\" href=\"#usage-examples\" title=\"Link to this heading\">\u00b6</a></h2><h3>Basic Connection<a class=\"headerlink\" href=\"#basic-connection\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"transport/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">transport<a class=\"headerlink\" href=\"#module-mcp.client.transport\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Transport Layer Implementation.</p><p>This module provides transport layer implementations for the MCP protocol.\nDifferent transports handle the underlying communication mechanism between\nthe MCP client and server.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
